gwrBase <- if (requireNamespace("jmvcore", quietly=TRUE)) R6::R6Class(
    "gwrBase",
    inherit = jmvcore::Analysis,
    public = list(
        initialize = function(options, data=NULL, datasetId="", analysisId="", revision=0) {
            super$initialize(
                package = "spatialfamily",
                name = "gwr",
                version = c(1,0,0),
                options = options,
                results = gwrResults$new(options=options),
                data = data,
                datasetId = datasetId,
                analysisId = analysisId,
                revision = revision,
                pause = NULL,
                completeWhenFilled = FALSE,
                requiresMissings = FALSE,
                weightsSupport = 'none')
        }))

#' Geographically Weighted Regression
#'
#' 
#' @param data .
#' @param dep .
#' @param covs .
#' @param xVar .
#' @param yVar .
#' @param idVar .
#' @param wLonLat .
#' @param kernel .
#' @param bwType .
#' @param bwMethod .
#' @param bw .
#' @param showLocal .
#' @param maps .
#' @param mapStat .
#' @param showGuide .
#' @param showHelp .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$diag} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$local} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mapPlots} \tab \tab \tab \tab \tab an array of images \cr
#'   \code{results$mapInt} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$saveR2} \tab \tab \tab \tab \tab an output \cr
#'   \code{results$saveResid} \tab \tab \tab \tab \tab an output \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$summary$asDF}
#'
#' \code{as.data.frame(results$summary)}
#'
#' @export
gwr <- function(
    data,
    dep,
    covs,
    xVar,
    yVar,
    idVar,
    wLonLat = FALSE,
    kernel = "bisquare",
    bwType = "adaptive",
    bwMethod = "aicc",
    bw = 30,
    showLocal = FALSE,
    maps = TRUE,
    mapStat = "coef",
    showGuide = FALSE,
    showHelp = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("gwr requires jmvcore to be installed (restart may be required)")

    if ( ! missing(dep)) dep <- jmvcore::resolveQuo(jmvcore::enquo(dep))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if ( ! missing(xVar)) xVar <- jmvcore::resolveQuo(jmvcore::enquo(xVar))
    if ( ! missing(yVar)) yVar <- jmvcore::resolveQuo(jmvcore::enquo(yVar))
    if ( ! missing(idVar)) idVar <- jmvcore::resolveQuo(jmvcore::enquo(idVar))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(dep), dep, NULL),
            `if`( ! missing(covs), covs, NULL),
            `if`( ! missing(xVar), xVar, NULL),
            `if`( ! missing(yVar), yVar, NULL),
            `if`( ! missing(idVar), idVar, NULL))


    options <- gwrOptions$new(
        dep = dep,
        covs = covs,
        xVar = xVar,
        yVar = yVar,
        idVar = idVar,
        wLonLat = wLonLat,
        kernel = kernel,
        bwType = bwType,
        bwMethod = bwMethod,
        bw = bw,
        showLocal = showLocal,
        maps = maps,
        mapStat = mapStat,
        showGuide = showGuide,
        showHelp = showHelp)

    analysis <- gwrClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

